/* 春日狂想曲·统一版 v10.6 · 24-statusbar.js · 源脚本：[非同层] 13-状态栏·天元录式注入 */
(function () {
  'use strict';
  var TOP = null;
  try { if (window.top && window.top.document) TOP = window.top; } catch (e) {}
  if (!TOP) { try { if (window.parent && window.parent.document) TOP = window.parent; } catch (e2) {} }
  if (!TOP) TOP = window;
  if (TOP.__HARU_SB__13) return;          // 注入器自身只初始化一次
  TOP.__HARU_SB__13 = 1;

  var SB_B64 = "";
  function b64u(b64) {
    var bin = atob(b64), n = bin.length, u = new Uint8Array(n), i;
    for (i = 0; i < n; i++) u[i] = bin.charCodeAt(i);
    return new TextDecoder('utf-8').decode(u);
  }
  var SB_HTML = b64u(SB_B64);

  function hostDoc() {
    try { if (TOP.document && TOP.document.body) return TOP.document; } catch (e) {}
    try { if (window.document && window.document.body) return window.document; } catch (e2) {}
    return null;
  }
  /* ── 更新记录（同天元录：版本页一个入口，点开是可滚动弹层） ───────────── */
  var CHG_URLS = [
    'https://raw.githubusercontent.com/cesareborgia576-cloud/haruharu-card/main/haruharu/changelog.json',
    'https://fastly.jsdelivr.net/gh/cesareborgia576-cloud/haruharu-card@main/haruharu/changelog.json',
    'https://gcore.jsdelivr.net/gh/cesareborgia576-cloud/haruharu-card@main/haruharu/changelog.json'
  ];
  var CHG_CACHE = null;

  function chgEsc(s) {
    return String(s).replace(/[&<>"]/g, function (c) {
      return ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c];
    });
  }

  function chgFetch(cb) {
    if (CHG_CACHE) { cb(CHG_CACHE); return; }
    var i = 0;
    function next() {
      if (i >= CHG_URLS.length) { cb(null); return; }
      var url = CHG_URLS[i++] + (CHG_URLS[i - 1].indexOf('raw.') >= 0 ? '' : '') + (CHG_URLS[i - 1].indexOf('?') >= 0 ? '&' : '?') + 't=' + Date.now();
      var done = false;
      var to = setTimeout(function () { if (!done) { done = true; next(); } }, 8000);
      try {
        fetch(url).then(function (r) {
          if (!r.ok) throw new Error('HTTP ' + r.status);
          return r.json();
        }).then(function (j) {
          if (done) return;
          done = true; clearTimeout(to); CHG_CACHE = j; cb(j);
        }, function () {
          if (done) return;
          done = true; clearTimeout(to); next();
        });
      } catch (e) { if (!done) { done = true; clearTimeout(to); next(); } }
    }
    next();
  }

  function openChg() {
    var doc = hostDoc(); if (!doc || !doc.body) return;
    if (doc.getElementById('haru-chg-mask')) return;

    var mask = doc.createElement('div');
    mask.id = 'haru-chg-mask';
    mask.setAttribute('style', 'position:fixed;inset:0;z-index:2147483600;background:rgba(8,8,12,.72);display:flex;align-items:center;justify-content:center;padding:20px;');
    mask.addEventListener('click', function (e) { if (e.target === mask) { try { mask.remove(); } catch (e0) {} } });

    var box = doc.createElement('div');
    box.setAttribute('style', 'width:min(560px,94vw);max-height:76vh;display:flex;flex-direction:column;background:linear-gradient(160deg,#16131c,#211a28);border:1px solid rgba(217,187,122,.45);border-radius:14px;box-shadow:0 18px 50px rgba(0,0,0,.7);overflow:hidden;font-family:system-ui,"Microsoft YaHei",sans-serif;color:#f2e9dc;');

    var head = doc.createElement('div');
    head.setAttribute('style', 'display:flex;align-items:center;gap:10px;padding:14px 16px;border-bottom:1px solid rgba(217,187,122,.22);flex:0 0 auto;');
    head.innerHTML = '<b style="flex:1;font-size:15px;color:#e6c884;letter-spacing:.5px;">📜 春日狂想曲 · 更新记录</b>';
    var x = doc.createElement('button');
    x.type = 'button';
    x.textContent = '✕';
    x.setAttribute('style', 'background:none;border:0;color:#9a8f80;font-size:16px;cursor:pointer;padding:2px 6px;');
    x.onclick = function () { try { mask.remove(); } catch (e1) {} };
    head.appendChild(x);

    var body = doc.createElement('div');
    body.setAttribute('style', 'padding:14px 16px;overflow-y:auto;flex:1 1 auto;font-size:13px;line-height:1.75;');
    body.innerHTML = '<div style="padding:26px;text-align:center;color:#8b8175;">读取更新记录…</div>';

    box.appendChild(head); box.appendChild(body); mask.appendChild(box);
    doc.body.appendChild(mask);

    chgFetch(function (data) {
      if (!data || !data.entries || !data.entries.length) {
        body.innerHTML = '<div style="padding:26px;text-align:center;color:#c98b8b;">读不到更新记录（网络或远端文件暂不可用）</div>';
        return;
      }
      var html = '';
      data.entries.forEach(function (e, i) {
        html += '<div style="margin:' + (i ? '18px' : '0') + ' 0 0;padding:0 0 0 12px;border-left:2px solid rgba(217,187,122,' + (i ? '.22' : '.55') + ');">';
        html += '<div style="display:flex;align-items:baseline;gap:8px;margin-bottom:6px;">';
        html += '<b style="color:#e6c884;font-size:14px;">' + chgEsc(e.ver || '') + '</b>';
        html += '<span style="color:#7d7469;font-size:11px;">' + chgEsc(e.date || '') + '</span>';
        html += '</div>';
        if (e.title) html += '<div style="color:#f2e9dc;font-weight:600;margin-bottom:5px;">' + chgEsc(e.title) + '</div>';
        html += '<ul style="margin:0;padding-left:18px;color:#c9c0b4;">';
        (e.items || []).forEach(function (t) { html += '<li style="margin:3px 0;">' + chgEsc(t) + '</li>'; });
        html += '</ul></div>';
      });
      body.innerHTML = html;
    });
  }

  /* 状态栏「⚙ 功能」页：内置插图 / 外置插图 两个开关 */
  function injectFunc(f) {
    var d;
    try { d = f.contentDocument; } catch (e) { return; }
    if (!d || d.getElementById('page-func')) return;
    var tabs = d.querySelector('.saku-tabs');
    var vpage = d.getElementById('page-version');
    if (!tabs || !vpage) return;

    var tab = d.createElement('span');
    tab.className = 'saku-tab';
    tab.setAttribute('data-page', 'page-func');
    tab.innerHTML = '<span class="saku-ico">⚙</span>功能';
    tabs.appendChild(tab);

    var pg = d.createElement('div');
    pg.className = 'saku-page';
    pg.id = 'page-func';
    pg.innerHTML = [
      '<div class="saku-page-title">功能</div>',
      '<div class="ver-row"><span class="ver-k">内置插图</span>',
      '<span class="ver-v" id="sb-fn-illust-v">—</span>',
      '<button type="button" class="ver-btn" id="sb-fn-illust">切换</button></div>',
      '<div class="ver-row"><span class="ver-k">外置插图</span>',
      '<span class="ver-v" id="sb-fn-ext-v">—</span>',
      '<button type="button" class="ver-btn" id="sb-fn-ext">切换</button></div>',
      '<div style="margin-top:10px;font-size:11px;color:#8a8175;line-height:1.75;">',
      '内置插图：卡里自带的图组（&lt;插图&gt; 标签）。<br>',
      '外置插图：st-chatu8 这类生图插件出的图，铺在游戏背景上，压在内置插图之上。</div>'
    ].join('');
    vpage.parentNode.appendChild(pg);

    function ls(k, dflt) {
      try { var v = localStorage.getItem(k); return v === null ? dflt : v; } catch (e) { return dflt; }
    }
    function paint() {
      var i1 = ls('SPR_ILLUST_ON', 'on') !== 'off';
      var i2 = ls('SPR_EXT_ILLUST', 'on') === 'on';
      try {
        d.getElementById('sb-fn-illust-v').textContent = i1 ? '开' : '关';
        d.getElementById('sb-fn-illust').textContent = i1 ? '关闭' : '打开';
        d.getElementById('sb-fn-ext-v').textContent = i2 ? '开' : '关';
        d.getElementById('sb-fn-ext').textContent = i2 ? '关闭' : '打开';
      } catch (e) {}
    }
    try {
      d.getElementById('sb-fn-illust').onclick = function () {
        var next = ls('SPR_ILLUST_ON', 'on') === 'off';
        try {
          if (TOP.__sprIllust) TOP.__sprIllust.set(next);
          else localStorage.setItem('SPR_ILLUST_ON', next ? 'on' : 'off');
        } catch (e) {}
        paint();
      };
      d.getElementById('sb-fn-ext').onclick = function () {
        var next = ls('SPR_EXT_ILLUST', 'on') !== 'on';
        try {
          if (TOP.__sprExtIllust) TOP.__sprExtIllust.set(next);
          else localStorage.setItem('SPR_EXT_ILLUST', next ? 'on' : 'off');
        } catch (e) {}
        paint();
      };
    } catch (eB) {}
    paint();
  }

  function injectChg(f) {
    var d;
    try { d = f.contentDocument; } catch (e) { return; }
    if (!d || d.getElementById('haru-chg-btn')) return;
    var page = d.getElementById('page-version');
    if (!page) return;
    var bar = d.createElement('div');
    bar.setAttribute('style', 'display:flex;gap:8px;margin-top:12px;flex-wrap:wrap;');
    var btn = d.createElement('button');
    btn.id = 'haru-chg-btn';
    btn.type = 'button';
    btn.className = 'ver-btn';
    btn.textContent = '📜 更新记录';
    btn.onclick = openChg;
    bar.appendChild(btn);
    page.appendChild(bar);
  }

  function mount(mesEl) {
    if (!mesEl) return;
    try { if (mesEl.getAttribute && mesEl.getAttribute('is_user') === 'true') return; } catch (e) {}
    var mt = mesEl.querySelector('.mes_text');
    if (!mt) return;
    if (mesEl.querySelector('.haru-sb-host')) return;   // 去重：挂在 .mes 上
    var doc = hostDoc(); if (!doc) return;
    var host = doc.createElement('div');
    host.className = 'haru-sb-host';
    host.style.cssText = 'margin:10px 0;clear:both;';
    var f = doc.createElement('iframe');
    f.className = 'haru-sb-frame';
    f.setAttribute('style', 'width:100%;border:0;background:transparent;height:600px;');
    f.setAttribute('sandbox', 'allow-scripts allow-same-origin');
    f.srcdoc = SB_HTML;
    host.appendChild(f);
    // 注入到 .mes_text 之后（兄弟节点），绝不进正文
    if (mt.parentNode) mt.parentNode.insertBefore(host, mt.nextSibling);
    else mesEl.appendChild(host);
    try {
      f.addEventListener('load', function () {
        try { var bd = f.contentDocument && f.contentDocument.body; if (bd) f.style.height = '600px'; } catch (e2) {}
        try { injectChg(f); } catch (e4) {}
        try { injectFunc(f); } catch (e5) {}
      });
    } catch (e3) {}
  }
  function scan() {
    var doc = hostDoc(); if (!doc || !doc.body) return;
    var list = doc.querySelectorAll('.mes');
    var last = null;
    for (var i = list.length - 1; i >= 0; i--) {
      var isU = false;
      try { isU = list[i].getAttribute('is_user') === 'true'; } catch (eU) {}
      if (!isU) { last = list[i]; break; }
    }
    if (last) mount(last);
    /* 只留最后一条 AI 消息上的状态栏，往上翻不留一堆 iframe */
    var hosts = doc.querySelectorAll('.haru-sb-host');
    for (var j = 0; j < hosts.length; j++) {
      if (!last || !last.contains(hosts[j])) { try { hosts[j].remove(); } catch (eR) {} }
    }
  }
  var timer = null;
  function schedule() { if (timer) return; timer = setTimeout(function () { timer = null; scan(); }, 400); } // debounce
  function start() {
    scan();
    try {
      var doc = hostDoc();
      if (doc && doc.body) { var o = new MutationObserver(function () { schedule(); }); o.observe(doc.body, { childList: true, subtree: true }); }
    } catch (e) {}
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start);
  else start();
})();